import { join } from 'node:path';
import { readJsonFile, workspaceRoot, type ProjectGraph } from '@nx/devkit';
import {
  createConformanceRule,
  type ProjectFilesViolation,
} from '@nx/powerpack-conformance';

export default createConformanceRule({
  name: 'project-package-json',
  category: 'consistency',
  description:
    'Ensure that project package.json files conform to the organizational standards',
  reporter: 'project-files-reporter',
  implementation: async (context) => {
    const violations: ProjectFilesViolation[] = [];

    for (const [sourceProject, node] of Object.entries(
      context.projectGraph.nodes
    )) {
      const sourceProjectRoot = node.data.root;
      const projectPackageJsonPath = join(
        workspaceRoot,
        sourceProjectRoot,
        'package.json'
      );

      if (!existsSync(projectPackageJsonPath)) {
        continue;
      }

      const projectPackageJson = readJsonFile(projectPackageJsonPath);

      violations.push(
        ...validateProjectPackageJson(
          projectPackageJson,
          sourceProject,
          sourceProjectRoot,
          projectPackageJsonPath
        )
      );
    }

    return {
      severity: 'medium',
      details: {
        violations,
      },
    };
  },
});

export function validateProjectPackageJson(
  projectPackageJson: Record<string, unknown>,
  sourceProject: string,
  sourceProjectRoot: string,
  projectPackageJsonPath: string
): ProjectFilesViolation[] {
  const violations: ProjectFilesViolation[] = [];

  // Private packages are not published and therefore not subject to these rules.
  if (projectPackageJson.private === true) {
    return violations;
  }

  const name = projectPackageJson.name;
  if (typeof name !== 'string') {
    violations.push({
      file: projectPackageJsonPath,
      message: 'The project package.json should have a "name" field',
      sourceProject,
    });
  } else if (name.startsWith('@') && !name.startsWith('@nx/')) {
    violations.push({
      file: projectPackageJsonPath,
      message: 'The package name should be scoped to the @nx org',
      sourceProject,
    });
  }

  const publishConfig = projectPackageJson.publishConfig as
    | Record<string, unknown>
    | undefined;
  if (!publishConfig || publishConfig.access !== 'public') {
    violations.push({
      file: projectPackageJsonPath,
      message:
        'Public packages should have "publishConfig": { "access": "public" } set in their package.json',
      sourceProject,
    });
  }

  if (
    existsSync(join(sourceProjectRoot, 'executors.json')) &&
    projectPackageJson.executors !== './executors.json'
  ) {
    violations.push({
      file: projectPackageJsonPath,
      message:
        'The project has an executors.json, but does not reference "./executors.json" in the "executors" field of its package.json',
      sourceProject,
    });
  }

  if (
    existsSync(join(sourceProjectRoot, 'generators.json')) &&
    projectPackageJson.generators !== './generators.json'
  ) {
    violations.push({
      file: projectPackageJsonPath,
      message:
        'The project has an generators.json, but does not reference "./generators.json" in the "generators" field of its package.json',
      sourceProject,
    });
  }

  const exports = projectPackageJson.exports;
  if (
    typeof exports !== 'object' ||
    exports === null ||
    Object.keys(exports).length === 0
  ) {
    violations.push({
      file: projectPackageJsonPath,
      message:
        'The project package.json should have an "exports" object specified',
      sourceProject,
    });
  }

  return violations;
}
